	[47] = {
		Title = "Pet System#Pet, Taming, Pet Egg, Evolution, Feeding ,Performance, Hatching",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00047",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Pet System allows you to tame monsters that appear in fields and dungeons into your own cute pet monsters.\nThe tamed monster always follows the owner, showing various performances, and depending on the unique ability of each pet, it is also very helpful to the owner.\n\n?<TIPBOX>Pet: Timing<INFO>48</INFO></TIPBOX>\n?<TIPBOX>Pet: Related NPCs<INFO>49</INFO></TIPBOX>\n?<TIPBOX>Pet: Interactions<INFO>50</INFO></TIPBOX>\n?<TIPBOX>Pet: Evolution<INFO>51</INFO></TIPBOX>\n?<TIPBOX>Pet List<INFO>10089</INFO></TIPBOX>\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[48] = {
		Title = "Pet: Timing#Petal",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00048",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"For taming a monster, a taming item suitable for the monster must be prepared.\nAfter preparing all the information and taming items of the monster you want to taming, double-click the taming item to target the targeted monster.\nWhen you target a monster, a slot machine appears in the center of the screen, and you can click on the slot machine to check taming success or failure.\n\nWhen the taming is successful, the message of acquiring the monster's egg is displayed along with the phrase Success, and you can check the monster's egg in the holding window.\n\n?<TIPBOX>Pet System<INFO>47</INFO></TIPBOX>\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[49] = {
		Title = "Pet: Related NPCs#Taming Merchant, Pet Food, Egg Incubator, Egg Incubator, Pet Food, Pet Accessories",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00049",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"?Pet Exchange Merchant\nIf you have a coupon that can be exchanged for a Pet, you can exchange it for a designated Pet through, ^3b488Pet Traders in Alberta and Prontera^000000.\n?<NAVI>[Alberta Pet Trader]<INFO>alberta,179,141,0,101,0</INFO></NAVI>\n?<NAVI>[Prontera Pet Trader]<INFO>prontera,210,209,0,101,0</INFO></NAVI>\n\n?Taming Merchant\nThey are located in each city and sells ^3b488cPortable Egg Incubator, Pet Food, Accessories^000000, etc.\n?<NAVI>[Prontera Pet Groomer]<INFO>prontera,218,211,0,101,0</INFO></NAVI>\n?<NAVI>[Geffen Pet Groomer]<INFO>geffen,193,152,0,101,0</INFO></NAVI>\n?<NAVI>[Izlude Pet Groomer]<INFO>izlude_in,72,98,0,101,0</INFO></NAVI>\n?<NAVI>[Morroc Pet Groomer]<INFO>morocc,203,87,0,101,0</INFO></NAVI>\n?<NAVI>[Morroc (Pyramid) Pet Groomer]<INFO>moc_ruins,118,170,0,101,0</INFO></NAVI>\n?<NAVI>[Payon Pet Groomer]<INFO>payon,177,131,0,101,0</INFO></NAVI>\n?<NAVI>[Yuno Pet Groomer]<INFO>yuno,197,114,0,101,0</INFO></NAVI>\n?<NAVI>[Lighthalzen Pet Groomer]<INFO>lighthalzen,222,191,0,101,0</INFO></NAVI>\n?<NAVI>[Brasilis Pet Groomer]<INFO>brasilis,201,309,0,101,0</INFO></NAVI>\n?<NAVI>[Lasagna Pet Groomer]<INFO>lasagna,179,176,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Pet System<INFO>47</INFO></TIPBOX>\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[50] = {
		Title = "Pet: Interactions#Hatching, Feeding, Performance, Intimacy, Hunger, Escape, Petal",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00050",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"If you ^3b488cright-click^000000 your hatched pet, you can see the pet menu.\n\nView Pet Status: You can check the status and information of your Pet.\nFeeding: Feed your pet.\nPerformance: Executes the unique performance of the pet.\nRemove Accessory: Removes the accessory item the pet is wearing.\nReturn to Egg: Returns the pet to it's pre-hatch state.\n\n?Pets that have successfully tamed can be renamed.\n?Feeding pets will improve intimacy with your pets.\nWhen the relationship with the pet becomes more than intimacy, additional abilities can be added in addition to the basic abilities.\nHowever, if you feed the pet too much or make the pet feel hungry by not feedi it,\nor if the master becomes incapacitated, the ^3b488cintimacy will decrease. If it continues to decline, the pet may disappear^000000, so please always take care of the pet you have tamed with interest and affection.\n?Pets can be returned to the egg state before hatching at any time, and can be hatched again using the \'Portable Egg Incubator\' item.\n\n?<TIPBOX>Pet System<INFO>47</INFO></TIPBOX>\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[51] = {
		Title = "Pet: Evolution#Pet Evolution",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00051",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Evolution is possible when a Pet's intimacy reaches ^3b488cCordial^000000.\nTo evolve, you need a ^3b488cPet Egg^000000 with Cordial Intimacy and ^3b488ccertain Materials^000000.\n\nOpen the Pet Info window and select the menu ^3b488c\'Evolution\'^000000 at the bottom.\n\n?After Evolution\n?Added automatic feeding function\n(As long as you turn on the auto-feeding function, it will be automatically feed. However, you must have food, and if you keep it without food, intimacy will decrease, so please be careful.)\n?Decreased intimacy increase\n (Intimacy increases very slowly.)\n?Penalty Reduction\n(Intimacy decreases slowly when hungry and no food is fed. Intimacy decreases when character is incapacitated.)\n?Reduced fullness consumption\n(The level of fullness decreases slowly compared to the pre-evolution pet.)\n\n?<TIPBOX>Pet System<INFO>47</INFO></TIPBOX>\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[52] = {
		Title = "Unequip",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00052",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"In the ^3b488cEquipment Window(Alt+Q)^000000, you can press the \"Unequip All\" button to unequip equipment at once.\n^3b488cGeneral/Special/Equipment Replacement Setting batch release function will be added later.^000000\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
