	},
	[70] = {
		Title = "Adventurer Agency",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00070",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can open the Adventurer Agency UI by pressing CTRL+Z.\nhe Adventurer Agency can recruit party members to enjoy Ragnarok together.\nIn order to register with the agency, you must enter the conditions of membership by pressing the adventure agency registration button while being the party leader. When joining someone else's party, you can apply to join the party according to the conditions set by the party leader.\n\n?<TIPBOX>Party System<INFO>29</INFO></TIPBOX>\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[71] = {
		Title = "Homunculus#Embryo,Bioethics,Creation,Lif,Amistr,Filir,Vanilmirth",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00071",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The alchemist classes can create and summon homunculus to help in battle through the \'Bioethics\' skill.\nRequirement: Level 60 or higher, Bioethics Quest completed\nPreparation: Geek Glasses, Grampa Beard, 20x Jellopy\nQuest Start Location: ?<NAVI>[Kellasus]<INFO>lhz_in01,224,140,0,101,0</INFO></NAVI>\n\If you have learned the \'Bioethics\' skill, you can make \'Embryo\' through the Potion Creation Guide and Pharmacy skill.\nMaterials: 1 Glass Tube, 1 Morning Dew of Yggdrasil, 1 Seed of Life, 1 Medicine Bowl\nThe higher the Pharmacy skill level, the creator's own level, and status, the higher the chance of success.\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[72] = {
		Title = "Stall Search#Catalog,item,Shop",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00072",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can use catalog items to search for or purchase items on the stall.\nThe number of searches and purchases varies for each catalog and targets stalls on the current map.\n?^i[12580] Window Shopper Catalog: search 10 times\n?^i[23368] Special Catalog Silver: Search, purchase 3 times\n\n?How to use\n* Select what type of stall you want to search for (Sell/Buy).\n* Select the item name. (Search for items containing words)\n* For carded items, add a prefix suffix.\n* If you want to search for an appropriate price range, add it.\n\n?Catalog Purchase Place\n* Paradise <NAVI>[Catalog Vending Machine]<INFO>moc_para01,22,16,0,101,0</INFO></NAVI>\n* Alberta Merchants Guild <NAVI>[Catalog Mage]<INFO>alberta_in,74,38,0,101,0</INFO></NAVI>\nSpecial Catalog Silver is available for purchase\n\n?<TIPBOX>Stall<INFO>67</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[73] = {
		Title = "Paradise#Teleport,Bulletin Board,Daily Quest,Beginner",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00073",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The Paradise Group is an organization that supports adventurers with what they need to survive in the world of Ragnarok.\nFrom equipment support for beginners to daily quests to help you level up!\n\nProntera ?<NAVI>[Eden Teleport Officer]<INFO>prontera,124,76,0,101,0</INFO></NAVI>\nIzlude ?<NAVI>[Eden Teleport Officer]<INFO>izlude,131,148,0,101,0</INFO></NAVI>\nMorroc ?<NAVI>[Eden Teleport Officer]<INFO>morroc,161,97,0,101,0</INFO></NAVI>\nMorroc(Pyramid Entrance) ?<NAVI>[Eden Teleport Officer]<INFO>moc_ruins,68,164,0,101,0</INFO></NAVI>\nComodo ?<NAVI>[Eden Teleport Officer]<INFO>comodo,202,151,0,101,0</INFO></NAVI>\nUmbala ?<NAVI>[Eden Teleport Officer]<INFO>umbala,105,158,0,101,0</INFO></NAVI>\nPayon ?<NAVI>[Eden Teleport Officer]<INFO>payon,177,111,0,101,0</INFO></NAVI>\nGeffen ?<NAVI>[Eden Teleport Officer]<INFO>geffen,132,66,0,101,0</INFO></NAVI>\nAlberta ?<NAVI>[Eden Teleport Officer]<INFO>alberta,124,67,0,101,0</INFO></NAVI>\nAldebaran ?<NAVI>[Eden Teleport Officer]<INFO>aldebaran,133,119,0,101,0</INFO></NAVI>\nYuno ?<NAVI>[Eden Teleport Officer]<INFO>yuno,144,189,0,101,0</INFO></NAVI>\nLighthalzen ?<NAVI>[Eden Teleport Officer]<INFO>lighthalzen,164,86,0,101,0</INFO></NAVI>\nEinbroch ?<NAVI>[Eden Teleport Officer]<INFO>einbroch,250,211,0,101,0</INFO></NAVI>\nHugel ?<NAVI>[Eden Teleport Officer]<INFO>hugel,93,153,0,101,0</INFO></NAVI>\nRachel ?<NAVI>[Eden Teleport Officer]<INFO>rachel,125,144,0,101,0</INFO></NAVI>\nVeins ?<NAVI>[Eden Teleport Officer]<INFO>veins,220,109,0,101,0</INFO></NAVI>\nLouyang ?<NAVI>[Eden Teleport Officer]<INFO>louyang,224,107,0,101,0</INFO></NAVI>\nBrasilis ?<NAVI>[Eden Teleport Officer]<INFO>brasilis,191,224,0,101,0</INFO></NAVI>\nAmatsu ?<NAVI>[Eden Teleport Officer]<INFO>amatsu,100,145,0,101,0</INFO></NAVI>\nPort Malaya ?<NAVI>[Eden Teleport Officer]<INFO>malaya,225,218,0,101,0</INFO></NAVI>\nAyothaya ?<NAVI>[Eden Teleport Officer]<INFO>ayothaya,221,191,0,101,0</INFO></NAVI>\nDewata ?<NAVI>[Eden Teleport Officer]<INFO>dewata,192,193,0,101,0</INFO></NAVI>\nMoscovia ?<NAVI>[Eden Teleport Officer]<INFO>moscovia,209,197,0,101,0</INFO></NAVI>\nKunlun ?<NAVI>[Eden Teleport Officer]<INFO>gonryun,162,122,0,101,0</INFO></NAVI>\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[74] = {
		Title = "Aircraft#Airplane,World Transfer,Oversea Flight,International Flight,Domestic Flight,Boarding,Schwartzvald,Arunafeltz,Rune-Midgards",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00074",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Oversea Flights\n?<NAVI>[Airship Staff]<INFO>izlude,202,75,0,101,0</INFO></NAVI>\nThe oversea airship departing from the satellite city of Izlude takes a route which passes through major overseas cities.\n - Izlude in Rune-Midgards Kingdom\n - Juno in the Schwartzvald Republic\n - Rachel at the Church of Arunafeltz\nA certain amount of zeny is consumed when boarding an airplane.\n\nSchwartzvald Domestic Flight\n?<NAVI>[Airport Staff]<INFO>y_airport,138,45,0,101,0</INFO></NAVI>\nSchwartzvald domestic airships are touring the Schwartzvald Republic.\n - Yuno\n - Hugel\n - Einbroch\n - Lighthalzen\nA certain amount of zeny is consumed when boarding an airplane.\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[75] = {
		Title = "Combine Cash Consumable Items#Jin Series, Small, Medium, Mysterious, Water of Life, Mana, Shining, Defense, Scroll, Almighty, Limited Edition, Power, Booster, Infinity, Drink, Red, ASPD, Enhanced Potion, Tyr's, Blessing, Mental, Combat Manual, Bubble Gum, Core, Practical, Infinite Fly Wings, Daily Box, Paradise Group",
