	[88] = {
		Title = "Effect Settings: Damage Display Extension#Maximum,Display,99999999999",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00088",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can expand the display limit of the maximum value of damage notation.\n(Basic Setting: Damage over 999999 is indicated as 999999)\nOpen game settings by pressing ESC or the option button.\nOn the Effect Settings tab\ncheck Expand Damage.\n\nYou can also change the damage display font.\n?<TIPBOX>Change damage Display Font<INFO>192</INFO></TIPBOX>\n\n?<TIPBOX>Effect Settings<INFO>143</INFO></TIPBOX>\n?<TIPBOX>Game Options Window<INFO>32</INFO></TIPBOX>\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
