	[91] = {
		Title = "Cash Purchase#Point, G-Cash, Recharge,Item Mall, Silvervine Cat Fruit",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00091",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can purchase items from anywhere by clicking the Cash Shop icon on the left side of the screen minimap. If you have free cash through events or coupons, you can use the free cash as much as you want by entering the available cash directly into the window.\nAfter logging in to the homepage, you can check the cash charge history.\n?<URL>Cash History<INFO>http://127.0.0.1/</INFO></URL>\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
