	[124] = {
		Title = "Divorce#Marriage, Proposal, Town Office",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00124",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can revoke your pledge of eternal love at the Prontera District Office or Niflheim.\n?Conditions\n?2.5 million Zeny\n\n?Subject to divorce\n?Married person\n\n?Place where divorce is possible\n?<NAVI>[Niflheim]<INFO>nif_in,190,112,0,101,0</INFO></NAVI>: Immediate divorce possible\n?<NAVI>[Prontera Town Office]<INFO>prt_in,282,165,0,101,0</INFO></NAVI>: Divorce is possible after a 4-day deliberation period.\n\n?<TIPBOX>Adoption<INFO>125</INFO></TIPBOX>\n?<TIPBOX>Marriage<INFO>123</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
