		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can improve game performance by increasing the program priority provided by Windows.\nThe default setting is Normal.\n\n?High: You can improve the slowdown phenomenon by utilizing more of the computer's resources.\n?Low: It can be helpful for running Ragnarok in a window screen and using other programs at the same time.\n\n?<TIPBOX>Basic Settings<INFO>33</INFO></TIPBOX>\n?<TIPBOX>Game Options Window<INFO>32</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
