		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Displays guild members and friends' login messages in the chat window.\n\n?Press ESC or the Options button to open the game settings.\nCheck Turn on login notifications in the Basic Settings tab.\n\n?Command\n/loginout, /li\n\n?<TIPBOX>Basic Settings<INFO>33</INFO></TIPBOX>\n?<TIPBOX>Game Options Window<INFO>32</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
