	[153] = {
		Title = "Control Settings: Mouse Snap#Target, Pickup ,Monster, Skill, Item, Snap, Game Settings",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Mouse Snap is a feature that automatically snaps to the selected target when the mouse cursor moves near it.\n\n1. Monster Target: If you move the mouse cursor near any monster, it will snap to it.\n2. Skill Target: If you move the mouse cursor to an enemy with the active shape of the target skill visible, it will snap to it.\n3. Pick Up Item: If you move the mouse cursor near a dropped item, it will snap to it. \n\n?Command\n/snap: Monster Target On/Off\n/skillsnap: Skill Target On/Off\n/itemsnap: Pick Up Items On/Off\n\n?<TIPBOX>Control Settings<INFO>152</INFO></TIPBOX>\n?<TIPBOX>Game Options Window<INFO>32</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[154] = {
		Title = "Control Settings:No Shift#Heal, Undead, Monster, Recovery, Target, Game Settings",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00154",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Special skills, such as the heal skill of the Acolyte job group, will heal when used on people, but can deal damage when used on undead enemies.\n\nSince the skills are used with conflicting functions, to prevent mistakes, when used on monsters, click with Shift to consider using it on monsters.\n\nIf you select this function, it will recognize that you are holding down Shift when using skills on monsters, allowing you to easily apply skills to monsters.\n\n?Command\n/noshift or /ns: No Shift On/Off\n\n?<TIPBOX>Control Settings<INFO>152</INFO></TIPBOX>\n?<TIPBOX>Game Options Window<INFO>32</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
