	[191] = {
		Title = "Useful Command List#Game Settings, Other Settings",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Here is a list of commands that are useful when used occasionally.\n\n/v: Check the sound effect volume.\n/v <number>: Adjust the sound effect volume to a numeric value.\n/bv: Check the background sound volume.\n/bv <number>: Adjust the background sound volume to a numeric value.\n/trade <character name>: Request a trade with a specific character.\n/guildinvite <character name>: Invite a specific character to the guild.\n/clanchat <message>: Send a message to a clan member.\n/web <website address>: Open a browser by entering the web page address.\n/naviopen: Open the navigation window.\n/navigation /navi <map name> <x/y> (example: /navi yuno 100/100): Guides you to the location you entered.\n/navigation2 /navi2 <map name> <location> <options> (example: /navi2 yuno 100/100 1/1/1 (scroll/zeny/plane: 1: use, 0: do not use)): Check the options to use for the small location and guide.\n\n?<TIPBOX>Other Settings and Gameplay Commands<INFO>166</INFO></TIPBOX>\n?<TIPBOX>Game Options Window<INFO>32</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[192] = {
		Title = "Change damage Display Font#Korean, Numbers, Settings, Display, Damage, Transparency, Attack, Game Settings",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00192",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can change the display of damage numbers when attacking monsters according to your preference.\nApplies only to your screen, and you can completely erase the damage display depending on your choice.\n\n1. Default: The currently applied basic damage number\n2. Number: A gradient is added to the outside of the number.\n3. Korean: The damage is displayed in Korean.\n4. Transparent: The damage is invisible.\n\nThe arrow next to the Default above determines whether the direction in which the damage number moves when it is generated and then disappears is fixed.\n\n1.  Default: The currently applied basic direction. The direction also changes depending on the screen rotation.\n2.: Fixed to flow diagonally to the right.\n3.: Fixed to flow only to the top center.\n4.: Fixed to flow diagonally to the left.\n\Path: Alt+Q -> Damage Display tab\n\nYou can change the damage display range.\n?<TIPBOX>Effect Settings: Damage Display Extension<INFO>88</INFO></TIPBOX>\n\n?<TIPBOX>Other Settings and Gameplay Commands<INFO>166</INFO></TIPBOX>\n?<TIPBOX>Game Options Window<INFO>32</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[193] = {
		Title = "Ranking: Taekwon",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"[Taekwon Boy/Girl]\nTaekwon Ranker:\nRankers (1st to 10th) will have their skills linked to Whirlwind Kick, Roundhouse Kick, Heel Drop, and Counter Kick.\nTaekwon Rankers of Level 90~99 will have their MaxHP and MaxSP tripled and can use all Taekwon skills.\n\n^3b488How to earn Ranking Points^000000\n1 Point: Earned every time you defeat 100 target monsters of a Taekwon Mission Skill.\nYou can find out the target monster by using the Taekwon Mission Skill.\n\nWhen you change jobs to a higher class, the Taekwon Ranker rewards will disappear.\n\nCheck Taekwondo Ranking: /taekwon\n\n?<TIPBOX>Ranking System<INFO>9082</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[194] = {
		Title = "Magic Book (Warlock Series)#Reading Spell Book",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"After changing to Warlock, the 3rd job of the Wizard, and learning the Reading Spellbook skill and the skill to save as a spell, you can rent magic books.\nHowever, not all magic books can be saved as spells, and some magic books can be rented only after completing quests.\n\nGeffen's Magic Book Manager:\n?<NAVI>[Velofos]<INFO>geffen_in,176,105,0,101,0</INFO></NAVI>\n?<NAVI>[Lea]<INFO>geffen_in,175,112,0,101,0</INFO></NAVI>\n\n?Intermediate Magic Books: Storm Gust, Lord of Vermillion, Meteor Storm\n?Advanced Magic Books: Drain Life, Jack Frost, Earth Strain, Crimson Rock, Chain Lightning\n?Ultimate Magic Books: Comet, Tetra Vortex (Ask Lea, Velofos. Level 140 or higher required)\n\n?A loan deposit may be required for all magic books, and if the magic book is lost, you can re-rent it by paying an additional loan deposit.\n\n?<TIPBOX>JQ Warlock<INFO>9058</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[195] = {
		Title = "Inventory: Favorite Tab#Shortcuts, Items",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00195",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can move items to your Favorite tab by Shift+Right-clicking in your inventory.\nThis shortcut can also be used when taking items out of the merchant's cart or storage (guild storage), and if there are identical items that can overlap in your inventory, they will not be moved to your personal tab but will overlap with the existing items.\nAlso, if you Shift+right-click an item in your personal tab, it will be moved to your normal tab.\n?<TIPBOX>Inventory: Item<INFO>64</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[900] = {
		Title = "World Map#map",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00900",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can view the World Map by clicking on the ^4d4dff\'World Map\'^000000 icon from the menu or by using the shortcut ^4d4dffCTRL+`^000000. Alternatively, you can show the World Map by clicking the button at the bottom right of the mini map.\n?^663399You can check Monsters Levels on the World Map by pressing the Tap key.^000000\n\n?<TIPBOX>World Movement<INFO>901</INFO></TIPBOX>\n?<TIPBOX>Navigation<INFO>902</INFO></TIPBOX>\n?<TIPBOX>Check your location<INFO>90</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[901] = {
		Title = "World Movement",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip00901",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"You can select the area you want to move to on the world map and use ^4d4dffFind^000000 to navigate directly, or use ^4d4dffMOVE^000000 by paying either ^4d4dffWorld Tour Ticket or a specific currency^000000 to teleport immediately. Intercity travel can be accomplished through space travel services such as Kafra and Airship. You can check the possible routes between cities on the world map.\n\n?<TIPBOX>World Map<INFO>900</INFO></TIPBOX>\n?<TIPBOX>Navigation<INFO>902</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[902] = {
