		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Varmundt's Biosphere is a space created by the Great Sage Varmundt in the mansion by imitating the natural environment and topography that actually exists for ecological research.\nIt had been neglected for a long time due to Varmundt's absence, but the manager of the mansion opened the tightly closed door, judging that the recent internal movement was unusual.\n\n?^663399Base Level: 240 or higher^000000\n\n?^663399Guidance NPC^000000\n?<NAVI>[Admin Beta]<INFO>ba_in01,252,353,0,101,0</INFO></NAVI>\n?<NAVI>[Admin Beta]<INFO>ba_in01,237,301,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Biosphere Reward<INFO>4322</INFO></TIPBOX>\n\n?^663399Biosphere Location^000000\n?<NAVI>[Specimen Environment - Severe Cold]<INFO>ba_in01,310,38,0,101,0</INFO></NAVI>\n?<NAVI>[Specimen Environment - Fire]<INFO>ba_in01,311,56,0,101,0</INFO></NAVI>\n?<NAVI>[Specimen Environment - Grassland]<INFO>ba_in01,325,56,0,101,0</INFO></NAVI>\n?<NAVI>[Specimen Environment - Death]<INFO>ba_in01,339,56,0,101,0</INFO></NAVI>\n?<NAVI>[Specimen Environment - Soul]<INFO>ba_in01,201,302,0,101,0</INFO></NAVI>\n?<NAVI>[Specimen Environment - Venom]<INFO>ba_in01,215,302,0,101,0</INFO></NAVI>\n?<NAVI>[Specimen Environment - Temple]<INFO>ba_in01,229,302,0,101,0</INFO></NAVI>\n?<TIPBOX>Varmundt Biosphere Deep Abyss<INFO>8368</INFO></TIPBOX>\n\n?<TIPBOX>Quest<INFO>4100</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
