	[4401] = {
		Title = "Tomb of the Fallen",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip04401",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The 'Tomb of the Fallen', a dungeon that has caused the disappearance of countless adventurers, tests your survival.\nIf you enter through Ohno Tohiro, the exit is close.\nYou can also enter through the child with black fingertips, but there is a machine nearby that requires more goods and allows all recovery. In addition, the 'Void of Vicious Mind', which can be entered through the child, is safe from monsters, but requires many additional goods and items.\n\n?Admission Information:\n?<NAVI>[Ohno Tohiro]<INFO>lighthalzen,321,218,0,101,0</INFO></NAVI>\n?<NAVI>[A Kid with Black Finger]<INFO>lighthalzen,320,204,0,101,0</INFO></NAVI>\n\n?Reward Information:\n?<NAVI>[Thug]<INFO>lighthalzen,312,296,0,101,0</INFO></NAVI>\n* The thug collects and condenses various types of energy fragments.\n\n?<NAVI>[Veteran Adventurer]<INFO>lighthalzen,319,213,0,101,0</INFO></NAVI>\n* The Veteran Adventurer collects numerous energy fragments and exchange them for the warrior's will, blood thirst, and chill of the dead.\n\n?<NAVI>[Wandering Mind]<INFO>lhz_dun_n,134,265,0,101,0</INFO></NAVI>: In the Dungeon\n?<NAVI>[Wandering Mind]<INFO>lhz_d_n2,42,49,0,101,0</INFO></NAVI>: In the Void of Vicious Mind\n* The Wandering Mind enchants the helmets of the Tomb of the Fallen.\n\n?<NAVI>[Silent Mind]<INFO>lhz_dun_n,145,265,0,101,0</INFO></NAVI>: In the Dungeon\n* The Silent Mind collects the souls of each class and exchanges them for the Chest of Death.\n\n?<NAVI>[Victimized Soul's Mind]<INFO>lhz_dun_n,143,265,0,101,0</INFO></NAVI>: In the Dungeon\n?<NAVI>[Victimized Soul's Mind]<INFO>lhz_d_n2,51,49,0,101,0</INFO></NAVI>: In the Void of Vicious Mind\n* The Victimized Soul's Mind exchanges the weapons in the Tomb of the Fallen for energy fragments.\n\n?<NAVI>[Sorrowful Soul's Mind]<INFO>lhz_dun_n,136,265,0,101,0</INFO></NAVI>: In the Dungeon\n?<NAVI>[Sorrowful Soul's Mind]<INFO>lhz_d_n2,44,49,0,101,0</INFO></NAVI>: In the Void of Vicious Mind\n* The Sorrowful Soul's Mind exchange helmets.\n\n?<NAVI>[Hot Machine]<INFO>lhz_d_n2,42,49,0,101,0</INFO></NAVI>: In the Void of Vicious Mind\n* The Hot Machine provides a guaranteed enchantment to the helmets of the Tomb of the Fallen.\n\n?<TIPBOX>Quest<INFO>4100</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[4402] = {
		Title = "Clock Tower Unknown Basement (240)",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip04402",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"In the inner corner of the first floor of the clock tower, a demon in a box is seeking help, unable to return to it's home.\nIf you wind up the nearby giant wind-up as the devil demands, you will be able to enter the unknown underground level.\n\n?Admission Information: \n?<NAVI>[Giant Clockwork]<INFO>c_tower1,244,198,0,101,0</INFO></NAVI>\n\n?Level Restrictions:\n?Base Level 240 or higher\n\n?Quest:\n?You can receive various quests from the box demon.\n?<NAVI>[Devil in the Box]<INFO>c_tower1,243,202,0,101,0</INFO></NAVI>\n\nDaily Quest:\n?Devil's Meal: Choose between killing 100, 300 or 1000 monsters\n?Devil's Pet Mimic: Talk to the pet Mimic inside the Unknown Basement.\n?Devil's Snack: Procure 100 snacks desired by the devil.\n\nWeekly Quest:\n?Devil's Special: Kill 5000 monsters\n* Resets every Monday at 4 AM\n\n?Shop:\n?If you cancel the conversation with <NAVI>[Devil in the Box]<INFO>c_tower1,243,202,0,101,0</INFO></NAVI>, a random store item will appear.\n聚nchant Item Shop\n蓄eapon Upgrade Exchange Shop\n?<TIPBOX>Fortify > Solid Series<INFO>4403</INFO></TIPBOX>\n?<TIPBOX>Relapse > Wicked Series<INFO>4404</INFO></TIPBOX>\n?<TIPBOX>Scrap > Precision Series<INFO>4405</INFO></TIPBOX>\n\n?<TIPBOX>Quest<INFO>4100</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
