	[6405] = {
		Title = "Temple Gimleh#Dungeon#240#Jormungand#Cult#Temple#Gimleh#Yoster#Yordos#Yormi#Yoskops#Yortus",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The Gimleh Temple of the Jormungand Cult is a place where you can meet the cult's followers, from the Yosters to the ruling class, the Jorthus. Please be mindful of your visit, as non-followers are not permitted.\n\n?^663399Entry Conditions^000000\n^FF0000Zeny, items, levels, or prerequisite quests are required to enter some areas within the dungeon.^000000\n\n?^663399Dungeon List^000000\n?<NAVI>[Temple Gimleh F1]<INFO>jor_tmple1,0,0,0,-222,1</INFO></NAVI>\n?<NAVI>[Temple Gimleh F2]<INFO>jor_tmple2,0,0,0,-222,1</INFO></NAVI>\n\n?<TIPBOX>To the dungeon page<INFO>6150</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[6406] = {
		Title = "Yorskalp Temple#Dungeon#250#Jormungand#Yordos#Yormi#Judge#Joscospus#Yordos",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The Jormungand Cult Temple, Yorskalp, is an annex to the Gimleh Temple and is inaccessible to Yosters of the devout class. Please be cautious when visiting, as more powerful and devout ones appear as monsters.\n\n?^663399Entry Conditions^000000\n^FF0000Zeny, items, levels, or prerequisite quests are required to enter some areas within the dungeon.^000000\n\n?^663399Dungeon List^000000\n?<NAVI>[Temple Yorscalp F1]<INFO>jor_sklf1,0,0,0,-222,1</INFO></NAVI>\n?<NAVI>[Temple Yorscalp F2]<INFO>jor_sklf2,0,0,0,-222,1</INFO></NAVI>\n\n?<TIPBOX>To the dungeon page<INFO>6150</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[6500] = {
		Title = "Yggdrasil Root#Dungeon#Nidhoggr#100",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"A cave discovered under a thick tree trunk in Splendide Field. Unlike the first floor where there are monsters, there are none on the second floor and instead there is a suspicious door at the end of the long cave.\n\n?^663399Entry Conditions^000000\n^FF0000Zeny, items, levels, or prerequisite quests are required to enter some areas within the dungeon.^000000\n\n?^663399Dungeon List^000000\n?<NAVI>[Yggdrasil Root 1st Floor]<INFO>nyd_dun01,0,0,0,-222,1</INFO></NAVI>\n?<NAVI>[Yggdrasil Root 2nd Floor]<INFO>nyd_dun02,0,0,0,-222,1</INFO></NAVI>\n\n?^663399Memorial Dungeons^000000\n?<TIPBOX>MD Nidhoggr's Nest<INFO>6505</INFO></TIPBOX>\n\n?^663399Others^000000\n?<TIPBOX>Q Nidhogg, Guardian of Yggdrasil, find the Truth (95)<INFO>6019</INFO></TIPBOX>\n\n?<TIPBOX>To the dungeon page<INFO>6150</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[6501] = {
		Title = "Bifrost Tower#Dungeon#Otherworld#Bifrost#Tower#140#150#Flowers#Blooming#Earth",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The Bifrost Tower is a tower you can encounter when you climb up the Bifrost vines to reach Eclage, the capital of Lapine. It is a great dungeon for adventurers of level 140-150 to challenge.\n\n?^663399Entry Conditions^000000\n^FF0000Zeny, items, levels, or prerequisite quests are required to enter some areas within the dungeon.^000000\n\n?^663399Dungeon List^000000\n?<NAVI>[Bifrost Tower F1]<INFO>ecl_tdun01,0,0,0,-222,1</INFO></NAVI>\n?<NAVI>[Bifrost Tower F2]<INFO>ecl_tdun02,0,0,0,-222,1</INFO></NAVI>\n?<NAVI>[Bifrost Tower F3]<INFO>ecl_tdun03,0,0,0,-222,1</INFO></NAVI>\n?<NAVI>[Bifrost Tower F4]<INFO>ecl_tdun04,0,0,0,-222,1</INFO></NAVI>\n\n?^663399Others^000000\n?<TIPBOX>EP 14.2 Eclage<INFO>6057</INFO></TIPBOX>\n?<TIPBOX>The Capital of Laphine, Eclage<INFO>4019</INFO></TIPBOX>\n\n?<TIPBOX>To the dungeon page<INFO>6150</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[6502] = {
		Title = "Flame Basin#Dugneon#Flame Basin#140#Flame#Basin",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The Flame Basin is a burning land where warriors of each race gather for the final battle with the Demon King Morroc. Fire-attribute monsters and Morroc's incarnations appear.\n\n?^663399Entry Conditions^000000\n^FF0000Zeny, items, levels, or prerequisite quests are required to enter some areas within the dungeon.^000000\n\n?^663399Dungeon List^000000\n?<NAVI>[Flame Basin]<INFO>moro_vol,0,0,0,-222,1</INFO></NAVI>\n\n?^663399Others^000000\n?<TIPBOX>Episode 14.3 Decisive Battle<INFO>6082</INFO></TIPBOX>\n\n?<TIPBOX>To the dungeon page<INFO>6150</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[6503] = {
		Title = "Scaraba Hole#Dungeon#Nightmare#Perfume",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Kamidal Tunnel on the way from Manouk to El Dicastes. It is also called Scaraba Dungeon because it is home to the insect-type monster Scaraba.\n\n?^663399Entry Conditions^000000\n^FF0000Zeny, items, levels, or prerequisite quests are required to enter some areas within the dungeon.^000000\n\n?^663399Dungeon List^000000\n?<NAVI>[Kamidal Tunnel]<INFO>dic_dun01,0,0,0,-222,1</INFO></NAVI>\n?<NAVI>[Scaraba Hall]<INFO>dic_dun02,0,0,0,-222,1</INFO></NAVI>\n\n?^663399Nightmare Dungeons^000000\n?<NAVI>[Scaraba Hall]<INFO>dic_dun03,0,0,0,-222,1</INFO></NAVI>\n\n?^663399Others^000000\n?<TIPBOX>Scaraba Hole Nightmare<INFO>6033</INFO></TIPBOX>\n\n?<TIPBOX>To the dungeon page<INFO>6150</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[6505] = {
		Title = "MD Nidhoggr's Nest(100)#MD#Yggdrasil#Guardian#100",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"A war between the two races, Lapine and Sapha, occurred when the voice of the guardian of the World Tree could no longer be heard. To find the truth, humans go to Nidhoggr's nest.\n?<NAVI>[Mysterious Door]<INFO>nyd_dun02,100,199,0,101,0</INFO></NAVI>\n\n?Prerequisites: <TIPBOX>Q Nidhogg, Guardian of Yggdrasil, find the Truth (95)<INFO>6019</INFO></TIPBOX> completed\n?<TIPBOX>Another World Entry Quest<INFO>6015</INFO></TIPBOX>\n?<TIPBOX>Q Interpreter (95)<INFO>6018</INFO></TIPBOX>\n\n?Dungeon Configuration\n?Repeatable every 3 days\n?Time Limit: 240 minutes\n?A dungeon consisting of two floors\n\n?<TIPBOX>Encounter with the Unknown<INFO>6016</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7055] = {
		Title = "Episode 17.1 appeared, Illusion#Quest Episode",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip07055",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The republican government, who was holding it's breath inside Schwartzvald, saw the opportunity and finally spread it's wings!\n\nSecret Wings and Rebellion became a temporary partnership.\nBefore the company's limbs are cut off in earnest, it will establish an operational base in Einbroch for mobility.\n\nAn urgent strike operation that starts with the pub, Cat on Bullet!\n\n?<TIPBOX>EP 16.2 - Terra Gloria<INFO>8149</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n\nStart Quest\n?<TIPBOX>Q New Operation Site <INFO>7056</INFO></TIPBOX>\n\n?Main Quest\n?<TIPBOX>Q Corporate Crisis<INFO>7057</INFO></TIPBOX>\n?<TIPBOX>Q Employment Road 01<INFO>7058</INFO></TIPBOX>\n?<TIPBOX>Q Old Memories<INFO>7059</INFO></TIPBOX>\n?<TIPBOX>Q The sky seen from the well<INFO>7060</INFO></TIPBOX>\n?<TIPBOX>Q Pure Evil Spirit<INFO>7061</INFO></TIPBOX>\n\nSide Quests\n?<TIPBOX>Q OS Conquest Operation<INFO>7062</INFO></TIPBOX>\n?<TIPBOX>Q Employment Road 02<INFO>7063</INFO></TIPBOX>\n?<TIPBOX>Q Morning Story<INFO>7064</INFO></TIPBOX>\n\n?Daily Quests\n?<TIPBOX>Q Mercenary VS Mercenary<INFO>7065</INFO></TIPBOX>\n?<TIPBOX>Q Caring for the farm<INFO>7066</INFO></TIPBOX>\n?<TIPBOX>Q EL1_A17T Suppression Operation<INFO>7067</INFO></TIPBOX>\n\n?<TIPBOX>Ep17.1 Illusion, OS Series<INFO>4110</INFO></TIPBOX>\n?<TIPBOX>Ep17.1 Grace Series<INFO>4114</INFO></TIPBOX>\n\n?<TIPBOX>Episode 17<INFO>4106</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7056] = {
		Title = "Q New Operation Site (110)#Quest Episode 17.1 Illusion Start",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The pub, Cat on Bullet, is located in Einbroch. In this seemingly ordinary tavern, government officials Tess and Rebellion launch a raid on the secret facility of the corporate research lab.\n\n?<TIPBOX>EP 16.2 - Terra Gloria<INFO>8149</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Philofontes]<INFO>pub_cat,93,105,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7057] = {
		Title = "Q Corporate Crisis (110)#Quest Episode 17.1 Illusion",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Tess introduces the company's personnel to the adventurer who returned after confirming the reality of Rudus.\nRegenschirm, an affiliated research institute of Rekenber, has been occupied by the assailants, so who is the person who asked for help to retake it...?\n\n?<TIPBOX>New Operation Site<INFO>7056</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Philofontes]<INFO>pub_cat,93,105,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7058] = {
		Title = "Q Employment Road 01 (110)#Quest Episode 17.1 Illusion",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Reiji, who has received a new assignment from the president, is raging in one of the Cat on Bullet's closets.\nHis opponent is Kaya Toss, vice president of Rekenber.\nCan the two start a journey together to uncover the hidden truth and reach the end safely?\n\n?<TIPBOX>Corporate Crisis<INFO>7057</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Reiji]<INFO>pub_cat,106,69,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7059] = {
		Title = "Q Old Memories (110)#Quest Episode 17.1 Illusion",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The old mines in Einbroch were already closed, but some researchers in the company were using them for new purposes.\nRebellion's elders have come forward to strike the illegal facility. I'm still on active duty.\n\n?<TIPBOX>Employment Road 01<INFO>7058</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Rebellion Crew]<INFO>ein_fild03,278,269,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7060] = {
		Title = "Q The sky seen from the well (110)#Quest Episode 17.1 Illusion",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"At the entrance of Cor, which you arrived after much effort, the workers there, who do not know the situation, are confronted with Rebellion's advance squad.\nEven Kaya, the vice president of Rekenber, goes out and convinces them, but it's not easy. Just as I was thinking about how to do it, a monster appears and attacks me...?\n\n?<TIPBOX>Old Memories<INFO>7059</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Rebellion]<INFO>sp_cor,168,81,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7061] = {
		Title = "Q Pure Evil Spirit (110)#Quest Episode 17.1 Illusion",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The escaped researcher Elyumina is evading the chase by engaging in guerrilla warfare.\nRebellion decides that it will be difficult to search for and restore her if she leaves Elyumina as she is, so she decides to seal off the Cor and launch a large-scale search operation.\n\n?<TIPBOX>The sky seen from the well<INFO>7060</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Rebellion]<INFO>sp_cor,108,130,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7062] = {
		Title = "Q OS Conquest Operation (110)#Episode 17.1 Illusion Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The advance has secured OS's railroad route, but it's not perfect.\nPrepare for Illusion's counterattack and help the annihilation battle to take complete control of OS.\n\n?There are daily quests that can be performed after completing the quests.\nOS 2nd Search(110)\n\n?<TIPBOX>Old Memories<INFO>7059</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Erst]<INFO>sp_cor,162,56,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7063] = {
		Title = "Q Employment Road 02 (110)#Episode 17.1 Illusion Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Cor where the Illusions gathered are to be studied. Convinced that this is a research institute where the missing people who disappeared after working for the Rekenber company were transferred, Kaya asks the adventurer to continue investigating the missing people.\n\n?There are daily quests that can be performed after completing the quests.\nBracelet Collection (110)\n\n?<TIPBOX>The sky seen from the well<INFO>7060</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Kaya Toss]<INFO>sp_cor,136,146,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7064] = {
		Title = "Q Morning Story (110)#Episode 17.1 Illusion Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Morning also comes to Rudus, where the useless subjects were abandoned. Even a child who was abandoned in the morning, but Morning, needs breakfast. How about making a friend by delivering a meal to him every morning?\n\n?There are daily quests that can be performed after completing the quests.\nMeal Delivery (110)\n\n?<TIPBOX>New Operation Site<INFO>7056</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Pile of Garbage]<INFO>sp_rudus,124,195,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7065] = {
		Title = "Q Mercenary VS Mercenary (110)#Episode 17.1 Illusion Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Rebellions are continuing their annihilation and search wars against OS. But we're having a hard time with these guys that keep popping up. Let's help them show the true taste of mercenaries.\n\n?<TIPBOX>Old Memories<INFO>7059</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Yuslan]<INFO>sp_cor,155,94,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7066] = {
		Title = "Q Caring for the farm (110)#Episode 17.1 Illusion Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"It's Cor, a laboratory where bloody experiments were conducted, but all kinds of crops are growing in one corner. Researchers and workers had to eat to survive.\nIt would be nice to take a break for a while while taking care of the crops in lieu of labor shortages.\n\n?<TIPBOX>Pure Evil Spirit<INFO>7061</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Farm Worker]<INFO>sp_cor,246,97,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7067] = {
		Title = "Q EL1_A17T Suppression Operation (110)#Episode 17.1 Illusion Daily Quest MD Memorial Dungeon",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Elyumina's children betrayed her? Half right and half wrong.\nElyumina's children go into low-power mode and hide somewhere in Cor. However, under the strong stimulus of being an adventurer, they can't get out of Elyumina's control and can't be forcefully shutdown.\nThe only way is to continuously consume power through steady battles!\n\n?<TIPBOX>Pure Evil Spirit<INFO>7061</INFO></TIPBOX> completed\n?^663399Level 110 or higher^000000\n?<NAVI>[Rebellion]<INFO>sp_cor,113,130,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7055</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7068] = {
		Title = "Episode 17.2 Sage's Legacy#Quest Episode",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip07068",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The adventurers and their companions entered to reclaim the mansion from Illusion, which is the mansion of the great sage Varmundt.\nIn anticipation of fierce resistance, they enter the place with firm determination, and unexpected characters are greeted by the party.\n\nWelcome to the sage's mansion.\n\n?<TIPBOX>EP. 17.1 appeared, Illusion<INFO>7055</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n\nStart Quest\n?<TIPBOX>Q The Mansion's Opening<INFO>7069</INFO></TIPBOX>\n\n?Main Quest\n?<TIPBOX>Q Sewer Fallout<INFO>7070</INFO></TIPBOX>\n?<TIPBOX>Q Guest of the mansion<INFO>7071</INFO></TIPBOX>\n?<TIPBOX>Q I want to know that<INFO>7072</INFO></TIPBOX>\n?<TIPBOX>Q Pest Control Operation<INFO>7073</INFO></TIPBOX>\n\nSide Quests\n?<TIPBOX>Q Coronation Ceremony<INFO>7074</INFO></TIPBOX>\n?<TIPBOX>Q Water Garden<INFO>7075</INFO></TIPBOX>\n?<TIPBOX>Q Quietly in the library<INFO>7076</INFO></TIPBOX>\n?<TIPBOX>Q Safe warehouse<INFO>7077</INFO></TIPBOX>\n?<TIPBOX>Q The bathroom, the strange creature and me<INFO>7078</INFO></TIPBOX>\n?<TIPBOX>Q The Forgotten Kennel<INFO>7079</INFO></TIPBOX>\n?<TIPBOX>Q Hidden Flower Garden<INFO>7080</INFO></TIPBOX>\n\n?Daily Quests\n?<TIPBOX>Q Sewage Treatment Plant, 1st Power Plant<INFO>7081</INFO></TIPBOX>\n?<TIPBOX>Q Illusion Sprinkled Potato Chips<INFO>7082</INFO></TIPBOX>\n\n?<TIPBOX>Ep17.2 Automatic Series<INFO>4111</INFO></TIPBOX>\n\n?<TIPBOX>Episode 17<INFO>4106</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7069] = {
		Title = "Q The Mansion's Opening(130)#Quest Episode 17.2 Start",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The sage's mansion was finally opened. But what does the entrance way look like...?\nLet's go through the sewage treatment plant that leads into the mansion and see if there is anyone left behind.\n\n?<TIPBOX>EP. 17.1 appeared, Illusion<INFO>7055</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Lucky]<INFO>sp_cor,255,285,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7070] = {
		Title = "Q Sewer Fallout (130)#Quest Episode 17.2 Start",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"As I was quickly breaking through the sewage treatment plant while alerting my surroundings, I heard an urgent sound from somewhere.\nWhen I approached the place with a vigilant eye, I met a nice person... right before he died?!\n\n?<TIPBOX>The Mansion's Opening<INFO>7069</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[???????????????]<INFO>ba_pw02,93,93,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7071] = {
		Title = "Q Guest of the mansion (130)#Episode 17.2 Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The automatons who were guarding the huge Varmundt's mansion somehow actively welcome the adventurers on the first day and express their intention to cooperate.\nAlpha registers as a guest according to the procedure, but says something went wrong and asks the adventurer for help.\n\n?There are daily quests that can be performed after completing the quests.\nNo Signal (130)\n\n?<TIPBOX>Sewer Fallout<INFO>7070</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Mansion Manager Alpha]<INFO>ba_maison,74,150,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7072] = {
		Title = "Q I want to know that (130)#Quest Episode 17.2",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"After re-investigating a past mercenary rebellion based on government records, Tess is puzzled to find out that there is a different point in contrast with the elders of Rebellion.\nTherefore, it is decided to re-investigate the witnesses who remember the old appearance of the mansion, which was the base at the time of the mercenary revolt.\n\n?<TIPBOX>Guest of the mansion<INFO>7071</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Philofontes]<INFO>ba_in01,206,106,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7073] = {
		Title = "Q Pest Control Operation (130)#Episode 17. MD Memorial Dungeon Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"After being promised corporate responsibility, the adventurer who went out to tour the mansion decided to collect the cores of the broken automatic dolls at the request of the mansion manager.\nThen, he meets an unexpected person who suddenly appears...!\nA party of adventurers holding the radar for tracking Illusion in their hands and chasing them to the very end!\n\n?There are 2 types of daily quests that can be performed after completing the quests.\nHey! Sweetie (130)\nCore Collection (130)\n\n?<TIPBOX>I want to know that<INFO>7072</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Rookie]<INFO>ba_maison,116,67,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7074] = {
		Title = "Q Coronation Ceremony (130)#Quest Episode 17.2",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"At the beginning of the long journey, there was the coronation of the Rune-Midgards Kingdom and the stolen Terra Gloria.\nNow that everything begins to take it's place, let's share the moment of the birth of a new king.\n\n?<TIPBOX>Pest Control Operation<INFO>7073</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Croux]<INFO>ba_maison,33,220,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7075] = {
		Title = "Q Water Garden (130)#Episode 17. MD Memorial Dungeon Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Elyumina, a science criminal who fell in love with the automatic dolls in the mansion at first sight. But it was unrequited love.\nHow about finding her cure for Elyumina, who became ill because of her unrequited love? I'm sorry and I'm in a boat now.\n\n?There are 4 daily quests that can be performed after completing the quests.\nWhereabouts of the Gardener (130)\nSilva Papilla Hunting (130)\nGrand Papillia Hunting (180)\nMD Water Garden (130, 180)\n\n?<TIPBOX>Guest of the mansion<INFO>7071</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Lensis]<INFO>ba_pw02,46,267,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7076] = {
		Title = "Q Quietly in the library (130)#Episode 17.2 Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Tamarin and his companions head to the library to investigate the sage's legacy. It's a well-preserved mansion, but this is too bad...? Besides, an unidentified guest?\n\n?There are 3 types of daily quests that can be performed after completing the quests.\nUltimate Scrap Collection (130)\nUltimate Bookworm (130)\nUltimate Theorem (130)\n\n?<TIPBOX>Guest of the mansion<INFO>7071</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Tamarin]<INFO>ba_maison,70,145,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7077] = {
		Title = "Q Safe warehouse (160)#Episode 17.2 Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The mansion of the great sage also has several large warehouses that are commensurate with its size. An adventurer who goes in to see one of them runs an errand on behalf of the extreme automatic doll he met there.\n\n?There are 2 types of daily quests that can be performed after completing the quests.\nGround Floor Warehouse Clearance (160)\nBasement Warehouse Clearance (170)\n\n?<TIPBOX>Guest of the mansion<INFO>7071</INFO></TIPBOX> completed\n?^663399Level 160 or higher^000000\n?<NAVI>[Chirp]<INFO>ba_2whs01,150,51,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7078] = {
		Title = "Q The bathroom, the strange creature and me (130)#Episode 17.2 Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"After passing the sewage treatment plant, I arrived at the bathroom to wash my dirty body. However, they say that there are monsters inside and they are blocking the entrance.\nAfter all, there must be at least one ghost in the old mansion.\n\n?There are 2 types of daily quests that can be performed after completing the quests.\nBetween hot and cold water (130)\nThe bathroom is being cleaned (130)\n\n?<TIPBOX>Guest of the mansion<INFO>7071</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Sinsa]<INFO>ba_in01,384,38,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7079] = {
		Title = "Q The Forgotten Kennel (130)#Episode 17. MD Memorial Dungeon Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Magnificent and beautiful breeding grounds located on one side of the mansion. It is home to meows and pitayas.\nHow about a tour of the kennel and a harvest experience under the guidance of the automatic doll?\n\n?There are 2 types of daily quests that can be performed after completing the quests.\nPitaya Tail Harvest (130)\nPlaying with Pitaya (150)\n\n?<TIPBOX>Guest of the mansion<INFO>7071</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Ruinan]<INFO>ba_maison,311,206,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7080] = {
		Title = "Q Hidden Flower Garden (130)#Episode 17.2 MD Memorial Dungeon Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The automatons who have been waiting for their homework but no one to check them want an adventurer with similar magical power to Varmundt to be evaluated as a temporary manager.\nBut it seems that each manager automata has a different idea...?\n\n?There are 2 types of daily quests that can be performed after completing the quests.\nSecurity Zone 1 (130)\nSecurity Zone 2 (180)\n\n?<TIPBOX>Guest of the mansion<INFO>7071</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Security Area Entry Officer]<INFO>ba_maison,120,321,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7081] = {
		Title = "Q Sewage Treatment Plant, 1st Power Plant (130)#Episode 17.2 Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The cleaning robot is cute... The small and cute cleaning robot Omega is sad that it cannot clean because of the terrifying monsters.\nLet's take the place of the cute little cleaning robot and deal with the monsters in the Sewage Treatment Plant and the 1st Power Plant.\n\n?<TIPBOX>Guest of the mansion<INFO>7071</INFO></TIPBOX> completed\n?^663399Level 130 or higher^000000\n?<NAVI>[Cleaner Omega]<INFO>ba_in01,30,329,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7082] = {
		Title = "Q Illusion Sprinkled Potato Chips (180)#Episode 17.2 MD Memorial Dungeon Daily Quest",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The Illusions have scattered jamming chips all over the 2nd Power Plant to block the radio waves of the automatic dolls.\nIt is fatal to automatic dolls, but it is a delicious nutritious snack for adventurers with life. I'll try one.\n\n?<TIPBOX>Guest of the mansion<INFO>7071</INFO></TIPBOX> completed\n?^663399Level 180 or higher^000000\n?<NAVI>[Eorpa]<INFO>ba_maison,79,278,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7068</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7083] = {
		Title = "Memorial Dungeon (MD)#Memorial Dungeon MD Reward",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Curiosity about the unknown leads to exploration. This is the fate of an adventurer.\nBeyond the continent of Midgard, to the new world, to the other world. A new story awaits adventurers to discover wherever their feet touch.\n\n?<TIPBOX>Midgard Continent MD List<INFO>7084</INFO></TIPBOX>\n?<TIPBOX>Episode MD List<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>MD Heroes Trails List<INFO>7129</INFO></TIPBOX>\n?<TIPBOX>MD EDDA List<INFO>7137</INFO></TIPBOX>\n?<TIPBOX>Region MD List<INFO>7141</INFO></TIPBOX>\n\n?<TIPBOX>Back to previous Page<INFO>4100</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7084] = {
		Title = "米德加尔特副本#古城波利塔保罗协夫星期兽人恐玩巴风特章鱼海神无限梦查尔斯顿",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"米德加尔特大陆，一个神话成为历史的地方。古老的故事和英雄的冒险故事在等着你。\n\t\t\n\t\t<TIPBOX>MD 神秘失事轮 (10)<INFO>7085</INFO></TIPBOX>\n\t\t<TIPBOX>MD 波利村 (30)<INFO>7086</INFO></TIPBOX>\n\t\t<TIPBOX>MD 保罗协夫实验室 (60)<INFO>7088</INFO></TIPBOX>\n\t\t<TIPBOX>MD 周末副本 (60)<INFO>7089</INFO></TIPBOX>\n\t\t<TIPBOX>MD 兽人的记忆 (60)<INFO>7090</INFO></TIPBOX>\n\t\t<TIPBOX>MD 恐怖玩具工厂<INFO>7091</INFO></TIPBOX>\n\t\t<TIPBOX>MD 余孽的大本营<INFO>7094</INFO></TIPBOX>\n\t\t<TIPBOX>MD 封印的神殿 (75)<INFO>7095</INFO></TIPBOX>\n\t\t<TIPBOX>MD 地下排水沟 (90)<INFO>7096</INFO></TIPBOX>\n\t\t<TIPBOX>MD 章鱼洞穴<INFO>7097</INFO></TIPBOX>\n\t\t<TIPBOX>MD 周五副本 (99)<INFO>7098</INFO></TIPBOX>\n\t\t<TIPBOX>MD 无限空间 (100)<INFO>7099</INFO></TIPBOX>\n\t\t<TIPBOX>MD 梦与影子 (120)<INFO>7100</INFO></TIPBOX>\n\t\t<TIPBOX>MD 查尔斯顿工厂 (130)<INFO>7101</INFO></TIPBOX>\n\t\t<TIPBOX>MD 古城<INFO>7102</INFO></TIPBOX>\n\t\t<TIPBOX>MD 克雷斯特汉姆古城<INFO>7102</INFO></TIPBOX>\n\t\t<TIPBOX>MD 星座塔 (240)<INFO>5002</INFO></TIPBOX>\n\t\t<TIPBOX>MD 沉没之塔 (40~249)<INFO>5003</INFO></TIPBOX>\n\t\t\n\t\t<TIPBOX>返回上一页<INFO>7083</INFO></TIPBOX>\n\t\t<TIPBOX>目录<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7085] = {
		Title = "MD Suspicious Shipwreck (10)#Beginner Lumine Reno",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Bran, a devotee of the goddess who made Leno and the adventurers tour the prison of Prontera. She heard information that he was on a suspicious wreck and came to find him.\n\n?Prerequisites: Proceed to Shipwreck Island\n?Dungeon Configuration\nOne-Time Scenario Dungeon\n?Time Limit: 60 minutes\n?Level 10 or higher\n?<NAVI>[Suspicious Shipwreck]<INFO>alb2trea,102,70,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7084</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7086] = {
		Title = "MD Poring Village (30)#Beginner Vegetables",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"There aren't many adventures that beginners can easily take on. But what if you had a temporary colleague who found those places first? Let's help each other and challenge each other.\n\n?Dungeon Configuration\n?Available every day (Resets at 04:00 the next day)\n?Time Limit: 30 minutes\n?Level 30 till 99\n?<NAVI>[Emily]<INFO>prt_fild05,145,235,0,101,0</INFO></NAVI>\n\nYou can obtain the following items during the dungeon raid:\n?<ITEM>[Poring Village Leek]<INFO>19238</INFO></ITEM> and <ITEM>[Poring Village Carrot]<INFO>19239</INFO></ITEM>  which can be enchanted at <NAVI>[Vegetable Enhancer]<INFO>prt_fild05,174,238,0,101,0</INFO></NAVI>.\n\n?<TIPBOX>Back to previous Page<INFO>7084</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7088] = {
		Title = "MD Borsev Lab (60)#Saint-Denrich Enterprises",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The subjects released by Borshev reached the point of attacking even the summoner. In order to control the subject, it is necessary to make the subject, the boss of the laboratory, incapable of combat.\n\n?Prerequisites: Complete the corporate quest/ Proceed with the story behind the company\n?Dungeon Configuration\n?Repeatable every 3 days\n?Time Limit: 240 minutes\n?Level 60 or higher\n?<NAVI>[Researcher]<INFO>lhz_dun04,151,276,0,101,0</INFO></NAVI>\n\n?Dungeon Raid Loot\n?<ITEM>[Will of Warrior]<INFO>6469</INFO></ITEM>\n?<ITEM>[Blood Thirst]<INFO>6470</INFO></ITEM>\n?<ITEM>[Ghost Chill]<INFO>6471</INFO></ITEM>\n?<ITEM>[Chilly Spell Book]<INFO>1584</INFO></ITEM>\n?<ITEM>[Guillotine Katar]<INFO>1291</INFO></ITEM>\n?<ITEM>[Giant Lance]<INFO>1490</INFO></ITEM>\n?<ITEM>[Ancient Gold Ornament]<INFO>18570</INFO></ITEM>\n?<ITEM>[Salvage Cape]<INFO>2582</INFO></ITEM>\n?<ITEM>[Bloody Cross]<INFO>16017</INFO></ITEM>\n\n?Equipment Exchange\n?<ITEM>[Will of Warrior]<INFO>6469</INFO></ITEM>, <ITEM>[Blood Thirst]<INFO>6470</INFO></ITEM>, <ITEM>[Ghost Chill]<INFO>6471</INFO></ITEM> can be exchanged for equipment at <NAVI>[Weird old man]<INFO>lighthalzen,342,291,0,101,0</INFO></NAVI>\n\nEquipment List\n?<ITEM>[Giant Shield]<INFO>2160</INFO></ITEM>\n?<ITEM>[Geffenia Water Book]<INFO>2161</INFO></ITEM>\n?<ITEM>[Bible of Promise Vol.2]<INFO>2162</INFO></ITEM>\n?<ITEM>[Salvage Cape]<INFO>2582</INFO></ITEM>\n?<ITEM>[Assassin's Handcuffs]<INFO>2892</INFO></ITEM>\n?<ITEM>[Green Operation Coat]<INFO>15044</INFO></ITEM>\n?<ITEM>[Ancient Gold Ornament]<INFO>18570</INFO></ITEM>\n?<ITEM>[Agent Katar]<INFO>1290</INFO></ITEM>\n?<ITEM>[Guillotine Katar]<INFO>1291</INFO></ITEM>\n?<ITEM>[Ygnus Stale]<INFO>1392</INFO></ITEM>\n?<ITEM>[End Sektura]<INFO>1393</INFO></ITEM>\n?<ITEM>[Cannon Spear]<INFO>1435</INFO></ITEM>\n?<ITEM>[Giant Lance]<INFO>1490</INFO></ITEM>\n?<ITEM>[Chilly Spell Book]<INFO>1584</INFO></ITEM>\n?<ITEM>[Light of Recovery]<INFO>1659</INFO></ITEM>\n?<ITEM>[Aztoe Nail]<INFO>13069</INFO></ITEM>\n?<ITEM>[Scarletto Nail]<INFO>13070</INFO></ITEM>\n?<ITEM>[Bloody Cross]<INFO>16017</INFO></ITEM>\n?<ITEM>[Catapult]<INFO>18109</INFO></ITEM>\n?<ITEM>[Big Crossbow]<INFO>18110</INFO></ITEM>\n?<ITEM>[Creeper Bow]<INFO>18111</INFO></ITEM>\n\nEquipment Enchancement and Reset\n?Available at the wizard in the Lighthalzen Cube Room\n\nEnchant equipment with <ITEM>[Will of Warrior]<INFO>6469</INFO></ITEM>, <ITEM>[Blood Thirst]<INFO>6470</INFO></ITEM>\nEnchant can be reset with <ITEM>[Ghost Chill]<INFO>6471</INFO></ITEM>\n\n?<TIPBOX>Back to previous Page<INFO>7084</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
