	[7090] = {
		Title = "MD Orc Memory (30)#O'Dawn",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The advisor is gone, but the research continues. A calm scientist is waiting for adventurers to explore after completing the gate to the ancient dimension in the Orc area.\n\n?Dungeon Configuration\n?Available every day (Resets at 04:00 the next day)\n?Time Limit: 30 minutes\n?Level 40 till 99\n?<NAVI>[Calm Scientist]<INFO>gef_fild10,231,203,0,101,0</INFO></NAVI>\n\n?Dungeon Raid Loot\n?<ITEM>[Ring of The Fallen]<INFO>28522</INFO></ITEM>\n?<ITEM>[Ring of Calamity]<INFO>28523</INFO></ITEM>\n\nRings can be strengthened with the help of <NAVI>[Suspicious Man]<INFO>gef_fild10,227,197,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7084</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
