	[7103] = {
		Title = "MD Old Glast Heim Beginner (65)#60",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"A researcher who introduces himself as a researcher who studies time and dimensions in an unusual outfit. It is said that beyond the rift of the stabilized dimension, it can stir up the internal cause and effect of the dungeon.\nBeing able to see Old Glast Heim with a beginner's body is not a bad suggestion.\n\n?Dungeon Configuration\n?Repeatable once per week (Reset at 04:00 every Thursday)\n?Time Limit: 60 minutes\n?Level 65 or higher\n?<NAVI>[Unusual Clown]<INFO>glast_01,196,235,0,101,0</INFO></NAVI>\n\n?Dungeon Raid Loot\n?<ITEM>[Temporal Crystal]<INFO>6607</INFO></ITEM>\n?<ITEM>[Coagulated Spell]<INFO>6608</INFO></ITEM>\n\n?<TIPBOX>Back to previous Page<INFO>7102</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
