	[7108] = {
		Title = "MD 14.1 Hazy Forest Labyrinth#Mora Guardian",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Where Laphines don't go? The Hazy Forest. Laphines, who guards the entrance to the place, finds humans strange, but helps them in. What the hell do you have?\n\n?Prerequisites:\n?<TIPBOX>Unsatisfied Greed, and humans go to another world<INFO>6005</INFO></TIPBOX> completed\n\n?Dungeon Configuration\n?Repeatable every 3 hours\n?Time Limit: 120 minutes\n?Daily Quest Level 99 or higher\n?<NAVI>[Laphine Soldier]<INFO>bif_fild01,158,340,0,101,0</INFO></NAVI>\n\n?Dungeon Raid Reward\n?Limited to 1 time\n?<ITEM>[Loki's Muffler]<INFO>2568</INFO></ITEM>\n?<ITEM>[Pendant of Guardian]<INFO>2858</INFO></ITEM>\n\n?Daily Quests\n?<ITEM>[Mora Coin]<INFO>6380</INFO></ITEM>\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7109] = {
		Title = "MD 14.3 Bios Island (160)#Warrior",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"A dream that has been repeated over and over again led the old man to the front of the yellow seed. Let's check the truth in the seed according to the old man who claims that it is the place where the Demon King Morroc is resurrected.\n\n?Prerequisites:\n?<TIPBOX>Burning Land<INFO>6083</INFO></TIPBOX> completed\n\n?Dungeon Configuration\n?Available every day (Resets at 04:00 the next day)\n?Time Limit: 60 minutes\n?Level 160 or higher\n?<NAVI>[Wandering Old Man]<INFO>moro_cav,45,60,0,101,0</INFO></NAVI>\n\n?Dungeon Raid Loot\n?<ITEM>[Prize of Hero]<INFO>22537</INFO></ITEM>\n?<ITEM>[Heroic Token]<INFO>6684</INFO></ITEM>\n\n?Prize of Hero Content (Randomly obtained)\n?<ITEM>[Heroic Plate]<INFO>15093</INFO></ITEM>\n?<ITEM>[Heroic Magic Coat]<INFO>15094</INFO></ITEM>\n?<ITEM>[Heroic Judgement Shawl]<INFO>15095</INFO></ITEM>\n?<ITEM>[Heroic Trade Mail]<INFO>15096</INFO></ITEM>\n?<ITEM>[Heroic Hidden Clothes]<INFO>15097</INFO></ITEM>\n?<ITEM>[Heroic Target Suit]<INFO>15098</INFO></ITEM>\n?<ITEM>[Heroic Nepenthes Shoes]<INFO>22035</INFO></ITEM>\n?<ITEM>[Heroic Silver Fox Leather Boots]<INFO>22036</INFO></ITEM>\n?<ITEM>[Heroic Ungoliant Boots]<INFO>22037</INFO></ITEM> and many other consumbles\n\n?Heroic Ring Exchange and Enchantment\n?<ITEM>[Heroic Ring]<INFO>2981</INFO></ITEM>\nRequired Items:\n?<ITEM>[Heroic Token]<INFO>6684</INFO></ITEM>\n?<NAVI>[Expert Enchanter Byrnes]<INFO>moro_cav,34,65,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7110] = {
		Title = "MD 14.3 Morse's Cave (160)#Warrior",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The senior chaser who traces Morroc's footsteps says that he can no longer trace it with his abilities and asks the adventurer for help.\n\n?Prerequisites:\n?<TIPBOX>Bios Island<INFO>7109</INFO></TIPBOX> completed\n\n?Dungeon Configuration\n?Available every day (Resets at 04:00 the next day)\n?Time Limit: 60 minutes\n?Level 160 or higher\n?<NAVI>[Senior Tracker]<INFO>moro_cav,61,69,0,101,0</INFO></NAVI>\n\n?Dungeon Raid Loot\n?<ITEM>[Prize of Hero]<INFO>22537</INFO></ITEM>\n?<ITEM>[Heroic Token]<INFO>6684</INFO></ITEM>\n\n?Prize of Hero Content (Randomly obtained)\n?<ITEM>[Heroic Plate]<INFO>15093</INFO></ITEM>\n?<ITEM>[Heroic Magic Coat]<INFO>15094</INFO></ITEM>\n?<ITEM>[Heroic Judgement Shawl]<INFO>15095</INFO></ITEM>\n?<ITEM>[Heroic Trade Mail]<INFO>15096</INFO></ITEM>\n?<ITEM>[Heroic Hidden Clothes]<INFO>15097</INFO></ITEM>\n?<ITEM>[Heroic Target Suit]<INFO>15098</INFO></ITEM>\n?<ITEM>[Heroic Nepenthes Shoes]<INFO>22035</INFO></ITEM>\n?<ITEM>[Heroic Silver Fox Leather Boots]<INFO>22036</INFO></ITEM>\n?<ITEM>[Heroic Ungoliant Boots]<INFO>22037</INFO></ITEM> and many other consumbles\n\n?Heroic Ring Exchange and Enchantment\n?<ITEM>[Heroic Ring]<INFO>2981</INFO></ITEM>\nRequired Items: \n?<ITEM>[Heroic Token]<INFO>6684</INFO></ITEM>\n?<NAVI>[Expert Enchanter Byrnes]<INFO>moro_cav,34,65,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7111] = {
		Title = "MD 14.3 Temple of the Demon God (160)#Warrior",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The Guardian, who was waiting for the adventurer in front of the tree where Morroc hid, opens the way to the hero for the final battle.\n\n?Prerequisites:\n?<TIPBOX>Demon Subjugation<INFO>6084</INFO></TIPBOX> completed\n\n?Dungeon Configuration\n?Available every day (Resets at 04:00 the next day)\n?Time Limit: 60 minutes\n?Level 160 or higher\n?<NAVI>[Guardian Nidhogg]<INFO>moro_cav,41,73,0,101,0</INFO></NAVI>\n\nAfter clearing the dungeon, you can obtain <ITEM>[Expedition Prize Box]<INFO>22567</INFO></ITEM> as reward\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7112] = {
		Title = "MD 15.2 Central Laboratory (135)#130",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The civilization explorer, who is worried about overworked work and a weak body, seems to be waiting only for adventurers.\n\n?Prerequisites:\n?<TIPBOX>Played Memory<INFO>10014</INFO></TIPBOX> Progress\n\n?Dungeon Configuration\n?Available every day (Resets at 04:00 the next day)\n?Time Limit: 60 minutes\n?Level 135 or higher\n?<NAVI>[Civilization Explorer]<INFO>verus01,149,155,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7113] = {
		Title = "MD 15.2 Last Room (150)",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Unlike the other rooms we've looked at so far, a solid-looking door is blocking the front of the group. When you think of the end of the survivors, you are reluctant to check beyond the door, but it is also an adventurer's job to face the truth.\n\n?Prerequisites:\n?<TIPBOX>Trace<INFO>10015</INFO></TIPBOX> completed\n\n?Dungeon Configuration\n?Available every day (Resets at 04:00 the next day)\n?Time Limit: 60 minutes\n?Level 150 or higher\n?<NAVI>[Verity]<INFO>verus01,123,181,0,101,0</INFO></NAVI>\n\nEquipment can be exchanged for <ITEM>[Complete Machine Part]<INFO>6827</INFO></ITEM> which can be aquired during the dungeon raid\n?Equipment Exchange\n?<ITEM>[Riot Chip]<INFO>18997</INFO></ITEM>\n?<ITEM>[Broken Chip 01]<INFO>28326</INFO></ITEM>\n?<ITEM>[Broken Chip 02]<INFO>28327</INFO></ITEM>\n?<NAVI>[Fruit]<INFO>verus01,151,173,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7114] = {
		Title = "MD 16.1 Blessed Ceremony (100)#Nelem",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The adventurer was honored to attend the throne ordinance as a hero.\nLet's watch the birth of a new king of the Rune-Midgards Kingdom.\n\n?Prerequisites:\n?<TIPBOX>Blessed Ritual<INFO>8120</INFO></TIPBOX> Progress\n\n?Dungeon Configuration\n?Solo Dungeon\n?One-Time Scenario Mode\n?Time Limit: 60 minutes\n?Level 100 or higher\nRing\nTalk to <NAVI>[Chamberlain Bell]<INFO>prt_cas_q,26,30,0,101,0</INFO></NAVI> to call Nelem.\n\n?<TIPBOX>Back to previous page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7115] = {
		Title = "MD 16.1 Room of Consciousness (100)#Nelem",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The royal families are looking for clues to track down the missing Terra Gloria. The clue can only be found in the past...\n\n?Prerequisites:\n?<TIPBOX>The clue of truth<INFO>8121</INFO></TIPBOX> completed\n\n?Dungeon Configuration\n?Solo Dungeon\n?Available every day (Resets at 04:00 the next day)\n?Time Limit: 60 minutes\n?Level 100 or higher\n\nTalk to <NAVI>[Chamberlain Bell]<INFO>prt_cas_q,26,30,0,101,0</INFO></NAVI> to call Nelem.\n\n?<TIPBOX>Dungeon Raid Loot<INFO>4108</INFO></TIPBOX>\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
