	[7116] = {
		Title = "MD 16.1 Air Fortress Invasion (145)#140 Lindy Hop Sunflower Juliette D. Rachel",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Scientists' efforts to restore a peaceful life have allowed them to enter the aerial fortress that invaded Prontera.\n\n?Prerequisites:\n?<TIPBOX>The clue of truth<INFO>8121</INFO></TIPBOX> completed\n\n?Dungeon Configuration\n?Repeatable every 3 days (Can be skipped if you have a Dungeon Ticket)\n?Time Limit: 60 minutes\n?Level 145 or higher\n?<NAVI>[Scientist Doyeon]<INFO>prt_q,249,79,0,101,0</INFO></NAVI>\n?<NAVI>[Scientist Doyeon]<INFO>dali02,122,63,0,101,0</INFO></NAVI>\n\n?Dungeon Raid Loot\n?<ITEM>[Lindy Hop]<INFO>21018</INFO></ITEM>\n?<ITEM>[Sunflower Boy]<INFO>2027</INFO></ITEM>\n?<ITEM>[Juliette de Rachel]<INFO>28010</INFO></ITEM>\n?<ITEM>[Vicious Mind Dagger]<INFO>28706</INFO></ITEM>\n?<ITEM>[Vicious Mind Saber]<INFO>13455</INFO></ITEM>\n?<ITEM>[Vicious Mind Spear]<INFO>1400</INFO></ITEM>\n?<ITEM>[Vicious Mind Mace]<INFO>16041</INFO></ITEM>\n?<ITEM>[Vicious Mind Rod]<INFO>1600</INFO></ITEM>\n?<ITEM>[Vicious Mind Violin]<INFO>1900</INFO></ITEM>\n?<ITEM>[Vicious Mind Wire]<INFO>1996</INFO></ITEM>\n?<ITEM>[Vicious Mind Book]<INFO>28605</INFO></ITEM>\n?<ITEM>[Vicious Mind Two-Handed Sword]<INFO>21016</INFO></ITEM>\n?<ITEM>[Vicious Mind Lance]<INFO>1450</INFO></ITEM>\n?<ITEM>[Vicious Mind Two-Handed Axe]<INFO>28107</INFO></ITEM>\n?<ITEM>[Vicious Mind Staff]<INFO>2026</INFO></ITEM>\n?<ITEM>[Vicious Mind Bow]<INFO>18121</INFO></ITEM>\n?<ITEM>[Vicious Mind Katar]<INFO>28008</INFO></ITEM>\n?<ITEM>[Vicious Mind Fist]<INFO>1800</INFO></ITEM>\n?<ITEM>[Vicious Mind Revolver]<INFO>13128</INFO></ITEM>\n?<ITEM>[Vicious Mind Huuma Shuriken]<INFO>13328</INFO></ITEM>\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
