	[7117] = {
		Title = "MD 16.2 Heart Hunter Military Base (100)#Outside of Base",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"The rebellions gathered to attack the Heart Hunter Base. Speed is vital if you don't want to leave any room for your enemies to counter.\n\n?Prerequisites:\n?<TIPBOX>Sediment<INFO>8147</INFO></TIPBOX> completed\n\n?Dungeon Configuration\n?Heart Hunter Military Base\n?One-Time Scenario Mode\nPrerequisite: Sediment completed\nAfter the scenario mode, you can attack MD Heart Hunters Military Base.\n?Time Limit: 60 minutes\n?Level 100 or higher\n\n\Outside the Heart Hunter Military Base\n?Available every day (Reset at 04:00 the next day)\n?Time Limit: 60 minutes\n?Level 100 or higher\n?<NAVI>[Julian]<INFO>ein_fild04,281,337,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Dungeon Raid Loot<INFO>4109</INFO></TIPBOX>\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[7118] = {
		Title = "MD Central Room (100)#Cute Siren",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Rebellion took full control of the lab with a quick blow. In order to find the missing Terra Gloria, you must quickly enter the central room.\n\n?Prerequisites:\n?<TIPBOX>Heart Hunter Military Base<INFO>7117</INFO></TIPBOX> completed\n\n?Dungeon Configuration\n?After clearing the One-Time Scenario Mode, it is possible to repeat it every day (Reset at 04:00 the next day)\n?Time Limit: 60 minutes\n?Level 100 or higher\n?<NAVI>[Rookie]<INFO>slabw01,236,91,0,101,0</INFO></NAVI>\n\n?<TIPBOX>Dungeon Raid Loot<INFO>4109</INFO></TIPBOX>\n\n?<TIPBOX>Back to previous Page<INFO>7107</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
