	[8090] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"为改造战斗核准备新增实验体。结束对普通人进行的移植实验。\n\n\t\t\t\t在伪装成总统会晤室的实验室里通过睡眠瓦斯等待实验体失去意识后入手。睡眠瓦斯和其他睡眠药物要注意用量避免影响到实验数据。\n\n\t\t\t\t战斗核的配置根据新实验体有所提升，移植时需要确认。" 
		}
	},
	[8091] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"第一阶段的目标为观察移植核之后的反应，确认实验体是否活着。因为增加了核的配置，移植时需要根据实验体进行细化调整。\n\n\t\t\t\t生存达到目标时间后直接进入第二阶段。" 
		}
	},
	[8092] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"第2阶段实验目标为观察生命体激发极限战斗力的过程，并且收录有用的数据。\n\n\t\t\t\t为进行第2阶段实验需要提供实验体激发战斗核极限力量的环境，测定极限值。\n\n\t\t\t\t各职业所需的环境不同，需要确认生命体个人档案，各个实验室要独立完成，实验完成后需要尽快提交实验报告。\n\n\t\t\t\t研究所长 保罗协夫" 
		}
	},
	[8093] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"移植成功后也会有无法使用战斗核力量的实验体。\n\n\t\t\t\t黑血反应(注: 吐出黑色血液的现象。严重的时候眼睛和耳朵，或者是已有伤口和新增伤口也会流出黑色血的现象)的实验体已确认无法回生。\n\n\t\t\t\t出现黑血反应后最快马上、最久在5个小时以内会陷入死亡状态，死亡后会有特异现象，称之为“思念体”……" 
		}
	},
	[8094] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"死亡后最多2日以内会出现思念体，第一个思念体拥有比较明确的意识，但很盲目的追从一个目标。\n\n\t\t\t\t该目标是会受到死亡前体验的刺激性情景和内容影响，但这仅仅是推测，实际需要测试。\n\n\t\t\t\t第一个思念体的话与生存时的模样几乎一样很难分辨，而且实验体的目标意识越强，形象越清晰。" 
		}
	},
	[8095] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"研究所长保罗协夫博士称为失败作的实验体伊格尼杰·塞尼亚的话，在思念体化后，之前的目标意识到对杀生的渴望。\n\n\t\t\t\t但，好像通过洗脑可以把杀生的渴望转换为对目标对象的仇敌状态。为了精准测定该现象，保罗协夫博士在亲自管理该生命体。" 
		}
	},
	[8096] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"除去特殊情况，在思念体化后分化成越多数量时，最初的目标会越来越模糊，最后只会热衷于杀人和破坏。\n\n\t\t\t\t已经无法管制的思念体几乎不可能重新管制，所以在进行思念体化时需要格外观察及隔离。" 
		}
	},
	[8097] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"改造核模拟依美乐的心脏，即战斗核移植到人类后可以进化成更强大的存在吗？对于这个问题的回答是，当然可以！\n\n\t\t\t\t但缺乏的只有一个，想生存的意志，不会被愤怒主宰的强大意识！还需要拥有强大精神力的个体！" 
		}
	},
	[8098] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"卢恩·米德加兹王国私下出行的非正式远征队，没能活着回来也不会留下记录的精锐冒险家们。\n\n\t\t\t\t这不就是为我而准备的实验体嘛！虽然有些困难，但以雷根贝勒的权力的话，可以跟卢恩·米德加兹的什么人士合力，在总统都神不知鬼不觉之下把他们拐过来。\n\n\t\t\t\t好，为他们的舞台准备好了。现在只能专注于实验让他们帮我们带来最完美的结果。" 
		}
	},
	[8099] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"啊……好困，这叫什么啊，好想回家，最近都没怎么回家，家里的猫咪看到我都开始哈气了。\n\n\t\t\t\t说什么实践更加美好的未来，记录什么生体实验记录，还把好好的东西换成破破烂烂的，什么企业啊，快倒闭吧……\n\t\t\t\t什么啊，这不是我的日记本啊，怎么擦不掉 &#%&@…\n\n\t\t\t\t^FF0000该研究员已开除，开除理由作为记录保存原文。^000000" 
		}
	},
	[8100] = {
		Title = "实验报告",
		Search = 0,
		Image = "蜡历牢磐其捞胶\\collection\\Tablet_IL",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"第1阶段目标是把心脏更换为战斗核后观察过程，生存时间达到目标值即刻进入第2阶段。\n\n\t\t\t\t第2阶段实验目标为观察生命体激发极限战斗力的过程，并且收录有用的数据。\n\n\n\t\t\t\t为进行第2阶段实验需要提供实验体激发战斗核极限力量的环境，测定极限值……\n\n\t\t\t\t需要注意不要过度刺激使其死亡，但现在100%的死亡率，作为对策问问思念体的意愿……" 
		}
	},
	[8105] = {
		Title = "Costume Design Competition Headgear Crafting#HatMm",
		Search = 1,
		Image = "蜡历牢磐其捞胶\\tipbox\\tip08105",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
