	[9031] = {
		Title = "角色: 职业",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"RO仙境传说的世界中，有着各种职业。\n\t\t\t\t<TIPBOX>1转职业转职说明<INFO>9032</INFO></TIPBOX>\n\t\t\t\t<TIPBOX>2转职业转职说明<INFO>9000</INFO></TIPBOX>\n\t\t\t\t<TIPBOX>转生职业相关说明<INFO>9051</INFO></TIPBOX>\n\t\t\t\t<TIPBOX>3转职业转职说明<INFO>9052</INFO></TIPBOX>\n\t\t\t\t<TIPBOX>4转职业转职说明<INFO>9135</INFO></TIPBOX>\n\n\t\t\t\t<TIPBOX>扩充职业转职说明<INFO>9039</INFO></TIPBOX>\n\t\t\t\t<TIPBOX>喵族说明<INFO>9044</INFO></TIPBOX>\n\n\t\t\t\t<TIPBOX>制造职业<INFO>9068</INFO></TIPBOX>\n\t\t\t\t<TIPBOX>回到角色页面<INFO>1001</INFO></TIPBOX>\n\t\t\t\t<TIPBOX>任务<INFO>4100</INFO></TIPBOX>\n\n\t\t\t\t<TIPBOX>查看目录<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9032] = {
		Title = "1st Job Change Guide",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Novices with Job Level 10 or higher can change their job to the 1st job. Be sure to master the Basic skills.\n?<TIPBOX>Swordman<INFO>9033</INFO></TIPBOX>\n?<TIPBOX>Acolyte<INFO>9034</INFO></TIPBOX>\n?<TIPBOX>Thief<INFO>9035</INFO></TIPBOX>\n?<TIPBOX>Archer<INFO>9036</INFO></TIPBOX>\n?<TIPBOX>Magician<INFO>9037</INFO></TIPBOX>\n?<TIPBOX>Merchant<INFO>9038</INFO></TIPBOX>\n\n?<TIPBOX>Go to Job page<INFO>9031</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9033] = {
		Title = "Swordman",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"A swordsman is a profession that has strong physical attack power and physical defense, and is strong enough to stand at the forefront of all characters and play the role of the vanguard.\n?^663399Job Level 10 or higher^000000\n?^663399Valid Job: Novice^000000\n?<NAVI>[Swordman]<INFO>izlude_in,74,172,0,101,0,</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>9032</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9034] = {
		Title = "Acolyte",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"According to the teachings of God, it is a profession that cannot use weapons for the purpose of killing the enemy. It is responsible for healing the opponent and helping the allies to fight easier through various prayers that amplify the allies's abilities.\n?^663399Job Level 10 or higher^000000\n?^663399Valid Job: Novice^000000\n?<NAVI>[Cleric]<INFO>prt_church,184,41,0,101,0,</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>9032</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9035] = {
		Title = "Thief",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"It uses a dagger as its main weapon, and although it has low stamina, it is a profession that specializes in evading enemy attacks or causing confusion with quick movements.\n?^663399Job Level 10 or higher^000000\n?^663399Valid Job: Novice^000000\n?<NAVI>[Thief Guide]<INFO>moc_prydb1,39,126,0,101,0,</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>9032</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9036] = {
		Title = "Archer",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"As a profession with a variety of talents in bow skills, it has excellent abilities in assisting colleagues to fire from a distance or to check the enemy.\n?^663399Job Level 10 or higher^000000\n?^663399Valid Job: Novice^000000\n?<NAVI>[Archer Guildsman]<INFO>payon_in02,64,67,0,101,0,</INFO></NAVI>\n\nArrows, which are essential for Archers, are sold by Arrow Merchants in each local weapon shop.\n\n?<TIPBOX>Back to previous Page<INFO>9032</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9037] = {
		Title = "Magician",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"It is a profession that specializes in magic using all the elements that exist in the world. It requires quick response to situations and judgment, but it is also a profession that boasts strong and splendor.\n?^663399Job Level 10 or higher^000000\n?^663399Valid Job: Novice^000000\n?<NAVI>[Mage Guildsman]<INFO>geffen_in,164,124,0,101,0,</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>9032</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9038] = {
		Title = "Merchant",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"They have various skills necessary for business. Utilizing carts or demonstrating the power of money, Mammonite will show their enemies the true taste of money and the power of a merchant with one thrilling shot.\n?^663399Job Level 10 or higher^000000\n?^663399Valid Job: Novice^000000\n?<NAVI>[Merchant]<INFO>alberta_in,56,43,0,101,0,</INFO></NAVI>\n\n?<TIPBOX>Back to previous Page<INFO>9032</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9039] = {
		Title = "Expanded Job Change Guide",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Novices with Job Level 10 or higher can also change jobs to Expanded Jobs. Be sure to master the Basic skills.\nUnlike the Basic 1st Job Change, the Expanded Jobs has a special way of changing to a higher job.\n\n?<TIPBOX>Taekwon<INFO>9040</INFO></TIPBOX>\n?<TIPBOX>Ninja<INFO>9041</INFO></TIPBOX>\n?<TIPBOX>Gunslinger<INFO>9042</INFO></TIPBOX>\n\n?<TIPBOX>Super Novice<INFO>9043</INFO></TIPBOX>\n\n?<TIPBOX>Go to Job page<INFO>1004</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9040] = {
		Title = "JQ Taekwon",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Taekwon is a job that use foot attacks as their main weapon. Weapons cannot be equipped, and other items which can be equipped by all Jobs except Novice either.\n?^663399Job Level 10 or higher^000000\n?^663399Valid Job: Novice^000000\n?<NAVI>[Phoenix]<INFO>payon_in01,62,10,0,101,0,</INFO></NAVI>\n\nTaekwons with Job Level 40 or higher will be able to change Jobs to the Extended 2nd Job.\n?<TIPBOX>Star Gladiator<INFO>9045</INFO></TIPBOX>\n?<TIPBOX>Soul Linker<INFO>9046</INFO></TIPBOX>\n\n?<TIPBOX>Back to previous Page<INFO>9039</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9041] = {
		Title = "JQ Ninja",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"A ninja with a special skill in quick movement uses not only general weapons, but also throwing weapons and ninjutsu, and is a hybrid job that can perform both physical and magical attacks as well as various evasion skills. Ninjas can take down enemies using daggers and shurikens, throwing non-swords weapons, and magic-like 搉injutsu?\n?^663399Job Level 10 or higher^000000\n?^663399Valid Job: Novice^000000\n?<NAVI>[Smuggler Captain]<INFO>alberta,168,138,0,101,0,</INFO></NAVI>\n\nNinjutsu tools and consumables necessary for ninjas are sold by ninjutsu vendors in each local weapon shop.\n\nNinjas with Base Level 99, Job Level 70 or higher will be able to change jobs to higher-level expanded jobs.\n?<TIPBOX>Kagerou/Oboro<INFO>9049</INFO></TIPBOX>\n\n?<TIPBOX>Back to previous Page<INFO>9041</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9042] = {
		Title = "JQ Gunslinger",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Gunslinger is a long-distance shooter that uses various firearms to subdue enemies. There are 5 types of firearms, all of which are two-handed weapons.\n?^663399Job Level 10 or higher^000000\n?^663399Valid Job: Novice^000000\n?<NAVI>[Master Miller]<INFO>que_ng,152,167,0,101,0,</INFO></NAVI>\n\nWeapons and consumables necessary for the Gunslingers are sold by the Ammunition Vendors in each local weapon shop.\n\nGunslingers with Base Level 99 and Job Level 70 or higher will be able to change jobs to higher-level expanded jobs.\n?<TIPBOX>Rebellion<INFO>9050</INFO></TIPBOX>\n\n?<TIPBOX>Back to previous Page<INFO>9039</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9043] = {
		Title = "JQ超级初心者转职",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"超级初心者与只会使用紧急治疗/装死的初心者不同，可以使用6个一转职业的大部分技能。超级初心者最大的魅力是可以习得大部分1转职业的技能。\n\t\t毕竟超级初心者也是一个职业，若你成为超级初心者则无法转职为其他1转职业。\n\t\t^663399 BaseLv45以上^000000\n\t\t^663399JobLv 10以上^000000\n\t\t^663399对象: 初心者^000000\n\n\t\t<NAVI>[特解雷诺]<INFO>aldeba_in,223,167,0,101,0,</INFO></NAVI>\n\t\t\n\t\tBaseLv200, JobLv(Job Level) 70以上超级初心者可以转职为上位扩展职业。\n\t\t<TIPBOX>终极初心者<INFO>4250</INFO></TIPBOX>\n\n\t\t<TIPBOX>返回到上一页<INFO>9039</INFO></TIPBOX>\n\t\t<TIPBOX>查看目录<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9044] = {
		Title = "JQ喵族引导",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"喵族作为出色的召唤师有着出色的能力，许多人都选择走向着召唤师这条路。\n\t\t作为冒险家的一名小萌新召唤师，正梦想着在米德加尔兹开启属于自己的探险之旅。\n\t\t\n\t\tBaseLv200, JobLv(Job Level) 60以上的召唤师可以转职为上位扩展职业。\n\t\t<TIPBOX>魂灵师<INFO>4251</INFO></TIPBOX>\n\n\t\t<TIPBOX>返回到上一页<INFO>9039</INFO></TIPBOX>\n\t\t<TIPBOX>查看目录<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9045] = {
		Title = "JQ Star Gladiator",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"Star Gladiator is a class that has the ability to convert the energy of the book into the attack power of your feet. The biggest feature of Star Gladiator is that it can be nurtured by specializing the character in your preferred hunting ground or monster.\n?^663399Job Level 40 or higher^000000\n?^663399Valid Job: Taekwon^000000\n?<NAVI>[Moohyun]<INFO>payon,215,102,0,101,0,</INFO></NAVI>\n\nThose with Base Level 99 and Job Level 50 or higher will be able to change jobs to higher-level expanded jobs.\n?<TIPBOX>Star Emperor<INFO>9047</INFO></TIPBOX>\n\n?<TIPBOX>Back to previous Page<INFO>9040</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9046] = {
		Title = "JQ Soul Linker",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"A Soul Linker is a profession that gives up the path of Taekwondo and gains the power of the soul. Soul Linker has a constitution that ignores status cancellation skills (Dispel, Hermod, Flying Kick).\n?^663399Job Level 40 or higher^000000\n?^663399Valid Job: Taekwon^000000\n?<NAVI>[Kid]<INFO>morocc_in,174,30,0,101,0,</INFO></NAVI>\n\nSoul Linkers with Base Level 99 and Job Level 50 or higher can change to higher-level expanded jobs.\n?<TIPBOX>Soul Reaper<INFO>9048</INFO></TIPBOX>\n\n?<TIPBOX>Back to previous Page<INFO>9040</INFO></TIPBOX>\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
	[9047] = {
		Title = "JQ星帝转职",
		Search = 1,
		Image = "",
