	[9167] = {
		Title = "Headgear Crafting#Headgear Costume Headband Crafting",
		Search = 1,
		Image = "",
		Imgcoord = { Position = 5, Size = 100 },
		Page = {
			"There are people in the world who make cool things out of various items. If you want to wear something special, let's try making a hat.\nYou can find hat craftsmen from around the world in the list of regions below.\n\nSome of the crafted hats can be exchanged for Costumes.\nBring a <ITEM>[Costume Exchange Coupon]<INFO>6697</INFO></ITEM> and certain hats to <NAVI>[Eve Patterson]<INFO>mal_in01,11,110,0,101,0</INFO></NAVI> to make an exchange.\nPlease refer to each document for details.\n\n?<TIPBOX>[Prontera]<INFO>9168</INFO></TIPBOX>\n?<TIPBOX>[Morroc]<INFO>9169</INFO></TIPBOX>\n?<TIPBOX>[Geffen]<INFO>9170</INFO></TIPBOX>\n?<TIPBOX>[Payon]<INFO>9171</INFO></TIPBOX>\n?<TIPBOX>[Lutie]<INFO>9172</INFO></TIPBOX>\n?<TIPBOX>[Alberta]<INFO>9173</INFO></TIPBOX>\n?<TIPBOX>[Aldebaran]<INFO>9174</INFO></TIPBOX>\n?<TIPBOX>[Comodo]<INFO>9175</INFO></TIPBOX>\n?<TIPBOX>[Yuno]<INFO>9176</INFO></TIPBOX>\n?<TIPBOX>[Einbech]<INFO>9177</INFO></TIPBOX>\n?<TIPBOX>[Lighthalzen]<INFO>9178</INFO></TIPBOX>\n?<TIPBOX>[Rachel]<INFO>9179</INFO></TIPBOX>\n?<TIPBOX>[Hugel]<INFO>9180</INFO></TIPBOX>\n?<TIPBOX>[Other Regions and Fields]<INFO>9181</INFO></TIPBOX>\n\n\n?<TIPBOX>View Tip List<INFO>1000</INFO></TIPBOX>"
		}
	},
